INSERT INTO goods (id, title, sub_title, goods_sn, cate_id, click_count, goods_number, price, market_price, relation_goods, goods_attr, goods_color, goods_version, goods_img, goods_gift, goods_fitting, goods_keywords, goods_desc, goods_content, is_delete, is_hot, is_best, is_new, goods_type_id, sort, status, add_time) VALUES (36, '至纯源石', '', '', 40, 100, 13426, 6.00, 6.00, '', '', '2,3', '', 'static/upload/20260630/1782819637723746200.png', '', '', '', '', '<table id="isPasted" style="font-size: 14px; background-color: rgb(248, 249, 250); color: rgb(32, 33, 34); margin: 1em 0px; border: 0.666667px solid rgb(162, 169, 177); border-collapse: collapse; max-width: 100%; display: table; box-shadow: rgba(0, 0, 0, 0.12) 0px 1px 3px, rgba(0, 0, 0, 0.24) 0px 1px 2px; border-radius: 4px; overflow: hidden; font-family: sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: center; width: 700px;"><thead><tr><th style="border: 0.666667px solid rgb(162, 169, 177); padding: 0.2em 0.4em; background-color: rgba(213, 215, 219, 0.4); color: rgb(32, 33, 34); text-align: center;">描述</th></tr></thead><thead><tr><th style="border: 0.666667px solid rgb(162, 169, 177); padding: 0.2em 0.4em; background-color: rgba(213, 215, 219, 0.4); color: rgb(32, 33, 34); text-align: center;">用途</th></tr></thead><tbody><tr><td style="border: 0.666667px solid rgb(162, 169, 177); padding: 0.2em 0.4em;">危险而又必不可少的物质。较为珍贵，用途多样。</td></tr><tr><td style="border: 0.666667px solid rgb(162, 169, 177); padding: 0.2em 0.4em;">在工业中用量巨大的源石结晶，但有着较高的提取难度。是世界的主要能源类精加工产物，同时也是几乎所有源石技艺得以施展的根本。如今，即使&ldquo;它会传播绝症&rdquo;的传言甚嚣尘上，也依旧没多少人能抵挡住它的诱惑。</td></tr></tbody></table>', 0, 1, 1, 0, 4, 0, 1, 1778833121);
